class Solution:
    def findMatrix(self, nums: list[int]) -> list[list[int]]:
        from collections import defaultdict
        count = defaultdict(int)
        res = []
        for x in nums:
            r = count[x]
            if r == len(res):
                res.append([])
            res[r].append(x)
            count[x] += 1
        return res

class Solution {
public:
    std::vector<std::vector<int>> findMatrix(std::vector<int>& nums) {
        std::vector<int> count(nums.size() + 1, 0);
        std::vector<std::vector<int>> res;
        for (int x : nums) {
            int r = count[x];
            if (r == (int)res.size()) {
                res.push_back({});
            }
            res[r].push_back(x);
            count[x]++;
        }
        return res;
    }
};

class Solution {
    public java.util.List<java.util.List<Integer>> findMatrix(int[] nums) {
        int[] count = new int[nums.length + 1];
        java.util.List<java.util.List<Integer>> res = new java.util.ArrayList<>();
        for (int x : nums) {
            int r = count[x];
            if (r == res.size()) {
                res.add(new java.util.ArrayList<>());
            }
            res.get(r).add(x);
            count[x]++;
        }
        return res;
    }
}

